PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'OWNER' CHECK(role IN('OWNER','GUEST')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS uq_control_user_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_control_users_tenant ON users(tenant_id,role);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('INCOME','EXPENSE')),icon TEXT,color TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS uq_control_category ON categories(tenant_id,name,type);
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('INCOME','EXPENSE')),description TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),category_id TEXT,status TEXT NOT NULL DEFAULT 'PAID' CHECK(status IN('PENDING','PAID','OVERDUE')),due_date TEXT,paid_at TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_control_tx_tenant_date ON transactions(tenant_id,due_date DESC,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_control_tx_tenant_type_status ON transactions(tenant_id,type,status);
CREATE TABLE IF NOT EXISTS goals(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,target_cents INTEGER NOT NULL CHECK(target_cents>0),current_cents INTEGER NOT NULL DEFAULT 0 CHECK(current_cents>=0),deadline TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_control_goals_tenant ON goals(tenant_id,deadline);
CREATE TABLE IF NOT EXISTS reserve_entries(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,amount_cents INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN('DEPOSIT','WITHDRAW')),note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS idx_control_reserve_tenant ON reserve_entries(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS debts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,total_cents INTEGER NOT NULL CHECK(total_cents>=0),remaining_cents INTEGER NOT NULL CHECK(remaining_cents>=0),due_date TEXT,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_control_debts_tenant ON debts(tenant_id,due_date);
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,email TEXT,code TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_control_invites_tenant ON invites(tenant_id,status);
CREATE TABLE IF NOT EXISTS debt_movements(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,debt_id TEXT NOT NULL,user_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(debt_id) REFERENCES debts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS idx_control_debt_movements ON debt_movements(tenant_id,debt_id,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT,action TEXT NOT NULL,entity TEXT,entity_id TEXT,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_control_audit ON audit_logs(tenant_id,created_at DESC,action);
